class Solution {
    public int findPeakElement(int[] nums) {
        int n = nums.length;
        for (int i = 0; i < n; i++) {
            long left = (i > 0) ? nums[i-1] : Long.MIN_VALUE;
            long right = (i + 1 < n) ? nums[i+1] : Long.MIN_VALUE;
            if (nums[i] > left && nums[i] > right) return i;
        }
        return 0;
    }
}

